def build_web_join_page() -> str:
    """Renders the responsive universal join and room browser landing page."""
    return """<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
  <title>Dump's Test - Join Battle Arena / ساحة التحدي</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap" rel="stylesheet">
  <style>
    * { box-sizing: border-box; }
    :root {
      --primary: #7b2cbf;
      --primary-glow: #b5179e;
      --gold: #ffd166;
      --green: #06d6a0;
      --red: #ef476f;
      --cyan: #4cc9f0;
      --bg-dark: #0b0914;
      --bg-card: #161224;
      --bg-item: #221b38;
      --border: #3d2f66;
    }
    body {
      background: radial-gradient(circle at top, #1c1438 0%, #0b0914 100%);
      color: #fff;
      font-family: 'Cairo', system-ui, -apple-system, sans-serif;
      margin: 0;
      padding: 16px;
      display: flex;
      flex-direction: column;
      align-items: center;
      min-height: 100vh;
    }
    .container {
      width: 100%;
      max-width: 540px;
      background: var(--bg-card);
      border: 2px solid var(--primary);
      border-radius: 20px;
      padding: 24px;
      box-shadow: 0 10px 40px rgba(123, 44, 191, 0.35);
    }
    .header-bar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 20px;
      border-bottom: 1px solid var(--border);
      padding-bottom: 12px;
    }
    .brand { display: flex; align-items: center; gap: 10px; }
    .brand h1 { color: var(--gold); font-size: 20px; margin: 0; font-weight: 900; }
    .badge {
      background: #ff477e;
      color: #fff;
      font-size: 11px;
      font-weight: 800;
      padding: 3px 8px;
      border-radius: 6px;
    }
    .btn-lang {
      background: var(--bg-item);
      border: 1px solid var(--border);
      color: var(--gold);
      font-size: 12px;
      font-weight: 700;
      padding: 6px 12px;
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
    }
    label {
      font-size: 12px;
      font-weight: 800;
      color: var(--gold);
      text-transform: uppercase;
      margin-bottom: 6px;
      display: block;
    }
    input {
      width: 100%;
      background: #0b0914;
      border: 1px solid var(--border);
      color: #fff;
      padding: 12px 14px;
      border-radius: 10px;
      font-size: 15px;
      font-family: inherit;
      margin-bottom: 14px;
    }
    .btn-action {
      width: 100%;
      background: linear-gradient(135deg, #7b2cbf 0%, #b5179e 100%);
      border: none;
      color: #fff;
      font-size: 15px;
      font-weight: 800;
      padding: 13px;
      border-radius: 12px;
      cursor: pointer;
      box-shadow: 0 4px 18px rgba(123, 44, 191, 0.4);
      font-family: inherit;
    }
    .room-item {
      background: var(--bg-item);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 12px;
      margin-bottom: 8px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .room-info h4 { margin: 0 0 4px 0; font-size: 14px; }
    .room-meta { font-size: 11px; color: #9d8ec2; }
    .btn-quick-join {
      background: var(--primary);
      border: none;
      color: #fff;
      font-size: 12px;
      font-weight: 800;
      padding: 6px 12px;
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
    }
  </style>
</head>
<body>
<div class="container">
  <div class="header-bar">
    <div class="brand">
      <span style="font-size:24px">👑</span>
      <h1>DUMP'S TEST <span class="badge">v16.0</span></h1>
    </div>
    <button class="btn-lang" id="btn-lang" onclick="toggleLang()">🇺🇸 English</button>
  </div>

  <div style="text-align:center;margin-bottom:20px;">
    <h2 style="color:var(--gold);margin:0 0 6px 0;font-size:22px" id="t-title">دخول ساحة التحدي</h2>
    <p style="color:#b8b0d0;font-size:13px;margin:0" id="t-sub">أدخل رمز الغرفة للقتال المباشر ضد أصدقائك</p>
  </div>

  <label id="lbl-code">رمز الغرفة (Room Code)</label>
  <input type="text" id="join-room-code" placeholder="ABC123" maxlength="6" style="text-transform:uppercase;letter-spacing:3px;text-align:center;font-weight:bold;font-size:20px;">

  <label id="lbl-name">اسمك في المعركة (Your Name)</label>
  <input type="text" id="join-player-name" placeholder="أدخل اسمك..." maxlength="16">

  <button class="btn-action" onclick="joinByCode()" id="btn-join">⚔️ دخول المعركة</button>

  <div style="margin-top:24px;">
    <label id="lbl-public">🌐 الغرف العامة المتاحة حالياً</label>
    <div id="rooms-list" style="margin-top:8px;">
      <div style="color:#9d8ec2;font-size:12px;text-align:center;padding:12px;" id="lbl-loading">جاري البحث عن غرف نشطة...</div>
    </div>
  </div>
</div>

<script>
  let isArabic = true;
  function toggleLang() {
    isArabic = !isArabic;
    localStorage.setItem("dumps_test_lang", isArabic ? "ar" : "en");
    applyLanguage();
  }
  function applyLanguage() {
    document.documentElement.lang = isArabic ? "ar" : "en";
    document.documentElement.dir = isArabic ? "rtl" : "ltr";
    document.getElementById("btn-lang").textContent = isArabic ? "🇺🇸 English" : "🇸🇦 العربية";
    document.getElementById("t-title").textContent = isArabic ? "دخول ساحة التحدي" : "Enter Battle Arena";
    document.getElementById("t-sub").textContent = isArabic ? "أدخل رمز الغرفة للقتال المباشر ضد أصدقائك" : "Enter room code to duel your friends online";
    document.getElementById("lbl-code").textContent = isArabic ? "رمز الغرفة (Room Code)" : "Room Code";
    document.getElementById("lbl-name").textContent = isArabic ? "اسمك في المعركة (Your Name)" : "Your Player Name";
    document.getElementById("btn-join").textContent = isArabic ? "⚔️ دخول المعركة" : "⚔️ JOIN BATTLE";
    document.getElementById("lbl-public").textContent = isArabic ? "🌐 الغرف العامة المتاحة حالياً" : "🌐 Active Public Rooms";
  }

  function joinByCode() {
    const code = (document.getElementById("join-room-code").value || "").trim().toUpperCase();
    const name = (document.getElementById("join-player-name").value || "").trim();
    if (code.length < 3) {
      alert(isArabic ? "الرجاء إدخال رمز غرفة صحيح (4 إلى 6 خانات)!" : "Please enter a valid room code (4 to 6 chars)!");
      return;
    }
    if (name) localStorage.setItem("dumps_test_player_name", name);
    window.location.href = `/room/${code}`;
  }

  function quickJoin(code) {
    const name = (document.getElementById("join-player-name").value || "").trim();
    if (name) localStorage.setItem("dumps_test_player_name", name);
    window.location.href = `/room/${code}`;
  }

  async function fetchRooms() {
    try {
      const res = await fetch("/api", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({action: "list_public_rooms"})
      });
      const data = await res.json();
      const listEl = document.getElementById("rooms-list");
      if (data.rooms && data.rooms.length > 0) {
        listEl.innerHTML = data.rooms.map(r => `
          <div class="room-item">
            <div class="room-info">
              <h4>${escapeHtml(r.room_name)} <span style="color:var(--gold)">#${r.room_code}</span></h4>
              <div class="room-meta">${isArabic ? 'المضيف' : 'Host'}: ${escapeHtml(r.host)} | 👥 ${r.player_count}/${r.max_players} | ${r.difficulty}</div>
            </div>
            <button class="btn-quick-join" onclick="quickJoin('${r.room_code}')">${isArabic ? 'انضمام' : 'JOIN'}</button>
          </div>
        `).join("");
      } else {
        listEl.innerHTML = `<div style="color:#9d8ec2;font-size:12px;text-align:center;padding:12px;">${isArabic ? 'لا توجد غرف عامة مفتوحة حالياً. أنشئ غرفتك الخاصة الآن!' : 'No public rooms available right now. Host your own!'}</div>`;
      }
    } catch(e) {
      document.getElementById("rooms-list").innerHTML = `<div style="color:#9d8ec2;font-size:12px;text-align:center;padding:12px;">${isArabic ? 'أدخل رمز الغرفة بالأعلى للانضمام' : 'Enter room code above to join'}</div>`;
    }
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, function(m) {
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m];
    });
  }

  const savedName = localStorage.getItem("dumps_test_player_name");
  const pNameInput = document.getElementById("player-name") || document.getElementById("join-player-name");
  if (pNameInput && savedName) pNameInput.value = savedName;
  if (localStorage.getItem("dumps_test_lang") === "en") {
    isArabic = false;
    applyLanguage();
  }
  if (typeof fetchRooms === "function") {
    fetchRooms();
    setInterval(fetchRooms, 6000);
  }
</script>
</body>
</html>"""


